@startuml

class Client {
  + Nin
  + Tin
  + Name
  + Address
}

class BicycleModel {
  + Name
  + Type
  + Gears
}

class Bicycle {
  + Number
}

class Store {
  + Name
  + Address
}

class Reservation {
  + PickupDay
}

class Rental {
  + ReturnDate
}

class BicycleType {
  ROAD
  MOUNTAIN
  BMX
  HYBRID
}

Client "1" -- "*" Reservation : makes
Client "1" -- "*" Rental : makes
BicycleModel "1" -- "*" Bicycle : is model for
BicycleModel "1" -- "*" Reservation : requested in
BicycleModel "1" -- "*" Rental : requested in
Store "1" -- "*" Reservation : pickup location
Store "1" -- "*" Rental : pickup location
Bicycle "1" -- "0..1" Rental : is picked up in
Reservation "1" -- "0..1" Rental : becomes

@enduml

